/*
 * A284895  Positions of 1 in A284893; complement of A284894.
 * https://oeis.org/A284895
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = position of the n-th 1 in A284893, the fixed point of
 *            0->01, 1->0111 (word generated by iterating the morphism)
 * Range:     u8 n <= 179, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 82 terms through n = 9948 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static unsigned char *A284895_w = NULL;
static size_t A284895_wlen = 0;
static uint64_t *A284895_pos = NULL;
static size_t A284895_plen = 0;

static void A284895_rebuild(void)
{
    size_t i, c = 0;
    for (i = 0; i < A284895_wlen; i++) if (A284895_w[i]) c++;
    free(A284895_pos);
    A284895_pos = (uint64_t *)malloc((c + 1) * sizeof(uint64_t));
    A284895_plen = 0;
    for (i = 0; i < A284895_wlen; i++)
        if (A284895_w[i]) A284895_pos[A284895_plen++] = (uint64_t)i + 1;
}

seq_t a(idx_t n)
{
    if (n < 1) return 0;
    if (A284895_wlen == 0) {
        A284895_w = (unsigned char *)malloc(1);
        A284895_w[0] = 0;
        A284895_wlen = 1;
        A284895_rebuild();
    }
    while (A284895_plen < (size_t)n) {
        size_t i, nl = 0, p = 0;
        for (i = 0; i < A284895_wlen; i++) nl += A284895_w[i] ? 4 : 2;
        unsigned char *nw = (unsigned char *)malloc(nl);
        for (i = 0; i < A284895_wlen; i++) {
            nw[p++] = 0; nw[p++] = 1;
            if (A284895_w[i]) { nw[p++] = 1; nw[p++] = 1; }
        }
        free(A284895_w);
        A284895_w = nw;
        A284895_wlen = nl;
        A284895_rebuild();
    }
    return (seq_t)A284895_pos[n - 1];
}
